package com.project.ai_ticket_triage.model;

import jakarta.persistence.*;
import java.time.Instant;

/**
 * JPA entity for a support ticket. Each instance maps to one row in the
 * "tickets" table in Postgres, which Hibernate creates automatically
 * (ddl-auto=update in application.properties).
 */
@Entity
@Table(name = "tickets")
public class Ticket {

    // Primary key, generated by the database
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    private String subject;

    // Default string columns are 255 characters, so allow longer ticket text
    @Column(length = 4000)
    private String body;

    // Store the enum as text ("NEW") instead of a number, so it stays readable and safe if the enum changes
    @Enumerated(EnumType.STRING)
    private TicketStatus status = TicketStatus.NEW;

    // Set once when the object is created
    private Instant createdAt = Instant.now();

    // Getters and setters (JPA and JSON serialization both need them)
    public Long getId() { return id; }
    public String getSubject() { return subject; }
    public void setSubject(String subject) { this.subject = subject; }
    public String getBody() { return body; }
    public void setBody(String body) { this.body = body; }
    public TicketStatus getStatus() { return status; }
    public void setStatus(TicketStatus status) { this.status = status; }
    public Instant getCreatedAt() { return createdAt; }
}
